/* Editable location layouts built from native vector objects. */
(function(){'use strict';const names=['Bedroom','Kitchen','Bathroom / toilet','Street','Inside shop','Office','Classroom','Living room','Park'];
function create(name){if(window.MorePlaces?.names.includes(name))return MorePlaces.create(name);const f={name,duration:4,tween:false,easing:'smooth',background:'#eee7d9',camera:{x:960,y:540,zoom:1,rotation:0},objects:[],cameraKeys:[],sounds:[]};const add=(type,x,y,w,h,fill,extra={})=>{const o={...M.make(type,x,y),w,h,...extra};if(fill)o.fill=fill;f.objects.push(o);return o},rect=(x,y,w,h,color,name)=>add('rect',x,y,w,h,color,{name:name||'Panel',radius:2}),label=(text,x,y,w=400,h=70,color='#364b4e')=>add('text',x,y,w,h,color,{text,fontSize:50,name:text});
function interior(wall='#e5dfd0',floor='#baa083'){rect(960,380,1920,760,wall,'Wall');rect(960,920,1920,400,floor,'Floor');rect(960,755,1920,22,'#f9f3e7','Skirting');for(let x=0;x<1920;x+=240)add('line',x,925,3,290,'#ad9276',{rotation:90});}
function windowAt(x,y){add('window',x,y,330,350,'#a1c5cd')}
if(name==='Bedroom'){interior('#dedfce','#bfa68e');windowAt(1350,360);add('curtain',1350,350,470,420,'#a68175');add('bed',490,790,720,370,'#8da89a');add('rug',1020,940,770,155,'#d2b990');add('table',980,760,200,220,'#b19678');add('lamp',980,577,110,240,'#dfbb79');add('alarm',985,639,90,90,'#cc8265');add('plant',1660,760,230,350);add('picture',480,340,240,270,'#b48763');add('clock',970,310,125,125);}
else if(name==='Kitchen'){interior('#e5e8db','#c7b99b');windowAt(1120,310);add('fridge',280,520,290,570,'#c5d3ca');for(let i=0;i<4;i++){rect(650+i*280,657,260,260,'#7eaaa1','Lower cabinet');rect(650+i*280,525,274,25,'#ead5b5','Countertop');rect(650+i*280,645,10,40,'#465b5a','Handle');}for(let i=0;i<2;i++){rect(570+i*260,220,240,250,'#b8cbbd','Wall cabinet');rect(570+i*260,245,10,35,'#465b5a','Handle');}rect(815,520,180,18,'#5b7678','Sink');add('line',815,465,70,10,'#566f70',{rotation:90});rect(1490,570,200,55,'#485a5b','Stove');for(let x of [1445,1535])add('circle',x,548,58,25,'#263c3e');rect(1490,685,180,130,'#384b4d','Oven');add('mug',1175,484,64,74,'#d49572');add('plant',1720,467,120,155);add('table',930,925,600,250,'#b08b67');add('chair',550,936,210,260,'#829a8c');}
else if(name==='Bathroom / toilet'){interior('#cde0dd','#b4c9c5');for(let x=0;x<1920;x+=160)add('line',x,380,760,2,'#b6cfcc',{rotation:90});for(let y=120;y<760;y+=140)add('line',960,y,1920,2,'#b6cfcc');rect(460,370,460,530,'#eef1e4','Shower');rect(460,370,405,485,'#a3c9ce','Shower glass');rect(620,380,8,100,'#5b777c','Shower handle');add('line',420,155,100,10,'#607c80');add('circle',455,165,90,28,'#607c80');rect(1310,638,390,240,'#83a69b','Vanity');add('circle',1310,510,440,95,'#f5f3e8',{name:'Basin'});add('line',1310,465,80,12,'#617d80',{rotation:90});rect(1310,255,400,310,'#7eaaa9','Mirror frame');rect(1310,255,370,280,'#c4dcdd','Mirror');rect(880,630,180,230,'#f4f1e6','Toilet tank');add('circle',880,754,245,150,'#f4f1e6',{name:'Toilet bowl'});add('circle',880,735,170,70,'#bed1d1');rect(880,837,120,160,'#eeeade','Toilet pedestal');add('rug',1330,921,540,180,'#d9b495');add('plant',1730,782,190,290);}
else if(name==='Street'){f.background='#c9dee1';rect(960,850,1920,460,'#60696b','Road');rect(960,671,1920,90,'#c1b6a3','Sidewalk');for(let x=100;x<1920;x+=350)rect(x,916,160,13,'#eee4c5','Road marking');add('building',240,335,340,580,'#96b2b2');add('shop',780,465,530,320,'#ca906d');add('building',1320,352,365,540,'#b9b99f');add('house',1740,439,370,365,'#cda889');add('streetlight',1030,410,90,530);add('tree',500,430,240,440);add('car',1420,839,470,230,'#ae6255');add('bench',360,665,310,150);}
else if(name==='Inside shop'){interior('#eee0cd','#c6aa84');for(let col=0;col<3;col++){const x=390+col*520;rect(x,375,410,530,'#997c61','Display cabinet');for(let row=0;row<3;row++){rect(x,235+row*160,400,14,'#d9bc94','Shelf');for(let i=0;i<4;i++)add(i%2?'book':'mug',x-145+i*95,190+row*160,60,74,['#d29978','#86a79a','#b9bf96','#ab8f9f'][i]);}}rect(1230,796,700,290,'#aa8366','Checkout counter');rect(1230,646,750,32,'#e4c9a5','Countertop');add('laptop',1220,586,190,115,'#506c6c');label('LITTLE MARKET',965,68,650,85);add('basket',350,880,210,220,'#a48869');}
else if(name==='Office'){interior('#dce3df','#b4a38e');windowAt(470,315);windowAt(900,315);add('shelf',1500,480,420,380,'#a48b72');add('plant',1720,777,190,350);add('chair',850,740,270,390,'#637f82');add('desk',940,841,900,340,'#bd9b76');add('laptop',985,610,260,185);add('mug',1260,645,70,80,'#a56956');add('book',659,670,180,65);add('clock',1520,180,130,130);}
else if(name==='Classroom'){interior('#e0deca','#bba386');rect(950,295,1060,380,'#9c7855','Board frame');rect(950,295,1020,340,'#3b6660','Chalkboard');label('A little lesson',970,250,700,100,'#eee8d4');label('A B C     1 2 3',970,365,600,60,'#eee8d4');add('clock',1660,230,135,135);for(let row=0;row<2;row++)for(let col=0;col<3;col++){const x=420+col*510,y=690+row*250;add('chair',x,y-30,150,210,'#7b9a94');add('desk',x,y,370,200,'#c2a077');add('book',x,y-89,95,45,'#af7464');}add('door',160,450,240,600,'#b79975');}
else if(name==='Living room'){interior('#e8ddc9','#baa287');windowAt(1450,315);add('sofa',690,765,760,350,'#8aa798');add('rug',1050,953,1120,180,'#ceb087');add('table',1070,878,420,240,'#a48769');add('mug',1070,772,70,75,'#b5775b');add('tv',1600,635,380,280);add('picture',620,330,300,270,'#c59170');add('lamp',220,643,150,430);add('plant',1260,650,170,290);}
else{f.background='#cde1df';rect(960,870,1920,420,'#96b68c','Grass');rect(960,967,1920,200,'#d4c5a4','Path');add('sun',1590,165,160,160);for(const [x,y] of [[230,440],[620,410],[1540,450],[1810,485]])add('tree',x,y,360,590);add('bench',1050,766,500,230);add('pond',420,813,480,160);add('bush',1470,782,300,160);add('flower',1670,847,65,120);}
return f;}
function insert(name){stop();remember();project.frames.splice(fi+1,0,create(name));fi++;selected=[];setTool('select');changed();toast(name+' added as a new editable frame.');}
function insertCustom(id){const def=project.customPlaces?.[id];if(!def)return;stop();remember();const f=clone(def),group='place_'+Math.random().toString(36).slice(2,11);f.objects.forEach(o=>{o.id=Math.random().toString(36).slice(2,11);o.group=group;o.locked=false});project.frames.splice(fi+1,0,f);fi++;selected=f.objects.map(o=>o.id);setTool('select');changed();$('#backToScene')?.click();toast('Place added. Click Ungroup to edit its objects separately.')}
function render(){const host=$('#libraryContent');host.innerHTML='<div class="pad"><button id="createPlace" class="primary wide">＋ Create a place in Custom canvas</button><p class="note">Choose a place. Each template creates a new frame with editable objects, leaving existing frames intact.</p></div><div id="placeCards" class="template-grid"></div>';$('#createPlace').onclick=()=>{ObjectStudio.open();$('#objectSaveMode').value='place';$('#objectSaveMode').onchange();};for(const [id,def] of Object.entries(project.customPlaces||{})){const card=document.createElement('div');card.className='template-card';card.innerHTML=`<canvas width="288" height="162"></canvas><h4>${esc(def.name)} · Custom</h4><button data-place-add class="primary wide">＋ Add location frame</button><div class="row"><button data-place-edit>Edit template</button><button data-place-delete>Delete template</button></div>`;M.render(card.querySelector('canvas').getContext('2d'),{...def,objects:def.objects.map(o=>M.hydrate(project,o))},0,288,162);card.querySelector('[data-place-add]').onclick=()=>insertCustom(id);card.querySelector('[data-place-edit]').onclick=()=>ObjectStudio.openPlace(id);card.querySelector('[data-place-delete]').onclick=()=>confirmDialog('Delete this place template?','Existing location frames will stay unchanged.',()=>{remember();delete project.customPlaces[id];changed();render()});$('#placeCards').append(card)}for(const name of names){const card=document.createElement('div');card.className='template-card';card.innerHTML=`<canvas width="288" height="162"></canvas><h4>${esc(name)}</h4><button class="primary wide">＋ Add location frame</button>`;M.render(card.querySelector('canvas').getContext('2d'),create(name),0,288,162);card.querySelector('button').onclick=()=>insert(name);$('#placeCards').append(card)}}
const button=document.createElement('button');button.dataset.tab='places';button.textContent='Places';$('.tabs').append(button);button.onclick=()=>{tab='places';$$('[data-tab]').forEach(b=>b.classList.toggle('active',b===button));renderLibrary()};const previous=renderLibrary;renderLibrary=function(){if(tab==='places')return render();previous()};const validateBeforePlaces=validateProject;validateProject=p=>{p=validateBeforePlaces(p);if(p.customPlaces){if(typeof p.customPlaces!=='object'||Array.isArray(p.customPlaces))throw Error('Invalid place library.');const entries=Object.values(p.customPlaces);if(entries.length>500)throw Error('Too many custom places.');for(const f of entries)validateBeforePlaces({version:1,fps:p.fps,characters:p.characters,images:p.images,frames:[f]});}return p};window.PlaceTemplates={names,create,insert,insertCustom};
})();
